17	  async #read(windowSec: number): Promise<Window & { estimated: number; resetAt: number }> {
18	    const windowMs = windowSec * 1000
19	    const now = Date.now()
20	    const current = Math.floor(now / windowMs)
21	    const stored = (await this.ctx.storage.get<Window>('w')) ?? {
22	      window: current,
23	      count: 0,
24	      prev: 0,
25	    }
26	    let { count, prev } = stored
27	    if (stored.window !== current) {
28	      prev = stored.window === current - 1 ? stored.count : 0
29	      count = 0
30	    }
31	    const elapsed = (now % windowMs) / windowMs
32	    return {
33	      window: current,
34	      count,
35	      prev,
36	      estimated: prev * (1 - elapsed) + count,
37	      resetAt: (current + 1) * windowMs,
38	    }
